<template><section class="agv-electrical"><header><div><small>电路导览</small><h2>{{electricalSource.title}}</h2></div><el-button :loading="reading" @click="openPage(2)">图纸目录</el-button></header><nav class="electrical-systems" aria-label="选择电路系统"><button v-for="group in electricalGroups" :key="group.id" type="button" :aria-pressed="selected.id===group.id" @click="selected=group">{{group.title}}</button></nav><AgvWirelessPower v-if="family==='latent'&&selected.id==='power'" :variant="variant" @source="value=>openPage(value.page,value.id)"/><article class="electrical-detail"><div class="electrical-description"><h3>{{selected.title}}</h3><p>{{selected.description}}</p><small>{{selected.evidence}}</small><div class="electrical-pages"><button v-for="page in selected.pages" :key="page.n" :disabled="reading" @click="openPage(page.n)"><span>{{page.title}}</span><small>PDF {{page.n}} 页 ↗</small></button></div></div><figure><el-image :src="referenceImage" :preview-src-list="[referenceImage]" fit="cover" preview-teleported><template #error><span class="photo-fallback">实物照片暂未加载</span></template></el-image><figcaption>{{family==='latent'?'现场实物对照 · 照片车型尚未确认':'对应车型说明书 · 整车结构'}}</figcaption></figure></article><p class="electrical-note">{{electricalSource.note}}</p><p v-if="error" role="alert" class="electrical-error">{{error}}</p><el-dialog v-model="visible" append-to-body class="agv-electrical-reader" :title="`${readerTitle} · 第${initialPage}页`" width="min(1300px,96vw)" top="3vh" destroy-on-close @closed="close"><PdfReader v-if="file" :file="file" :initial-page="initialPage"/></el-dialog></section></template>
<script setup>
import {ref,computed,onBeforeUnmount} from 'vue'
import {electricalCatalog} from '../../utils/agv-electrical.mjs'
import {previewKnowledgeFileResponse} from '../../api'
import PdfReader from '../PdfReader.vue'
import AgvWirelessPower from './AgvWirelessPower.vue'
const props=defineProps({variant:{type:String,default:'old'},family:{type:String,default:'latent'}})
const {source:electricalSource,groups:electricalGroups}=electricalCatalog(props.variant,props.family)
const referenceImage=computed(()=>props.family==='latent'?`/models/agv-reference/photo-${selected.value.photo}.jpg`:`/models/agv-reference/${props.family}.webp`)
const readerTitle=ref(electricalSource.title)
const selected=ref(electricalGroups[0]),reading=ref(false),visible=ref(false),file=ref(null),initialPage=ref(2),error=ref('');let request=0,disposed=false
async function openPage(page,entryId=electricalSource.knowledgeId){if(reading.value)return;const id=++request;reading.value=true;error.value='';initialPage.value=page;readerTitle.value=({12:'无线供电站原理',17:'超级电容原理',19:'无线供电与取电接线'})[entryId]||electricalSource.title;try{const result=await previewKnowledgeFileResponse(entryId);if(disposed||id!==request)return;if(!result.blob.type.includes('pdf'))throw Error();file.value=result.blob;visible.value=true}catch{if(!disposed&&id===request)error.value='电路原图暂时无法读取，请稍后重试。'}finally{if(!disposed&&id===request)reading.value=false}}
function close(){request++;file.value=null}onBeforeUnmount(()=>{disposed=true;close()})
</script>
<style scoped>.agv-electrical{background:#fff;border:1px solid #e0e8ef;border-radius:14px;padding:24px}.agv-electrical>header{display:flex;align-items:center;justify-content:space-between;gap:12px}.agv-electrical header small{font-size:10px;color:#4e919e;letter-spacing:.12em}.agv-electrical h2{font-size:19px;margin:7px 0 0;font-weight:600;color:#254258}.electrical-flow{padding:20px 0;margin:5px 0 20px}.electrical-flow svg{width:100%;display:block;max-height:230px}.electrical-flow svg g{cursor:pointer}.electrical-flow>small{display:block;text-align:center;font-size:10px;color:#91a5b0;margin-top:8px}.electrical-detail{display:grid;grid-template-columns:minmax(0,1fr) 40%;gap:22px;border-top:1px solid #eaf0f4;padding-top:22px}.electrical-detail h3{font-size:16px;color:#2c5265;margin:0 0 12px}.electrical-detail p{font-size:12px;line-height:1.9;color:#728799;margin:0 0 10px}.electrical-description>small{font-size:10px;color:#90a3b1}.electrical-pages{margin-top:15px;display:grid;gap:3px}.electrical-pages button{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:10px 0;border:0;border-bottom:1px solid #edf2f5;text-align:left;background:none;color:#3d7e90;cursor:pointer;font:inherit;font-size:12px}.electrical-pages small{font-size:10px;color:#90a4b1;white-space:nowrap}.electrical-detail figure{margin:0}.electrical-detail .el-image{width:100%;height:230px;border-radius:10px;background:#f1f5f7}.electrical-detail figcaption{font-size:10px;line-height:1.7;margin-top:8px;color:#94a6b3}.photo-fallback{display:grid;place-items:center;height:100%;font-size:12px;color:#91a1ae}.electrical-note{font-size:10px;line-height:1.8;color:#a2b0ba;margin:22px 0 0}.electrical-error{color:#ac4150;font-size:12px}@media(max-width:1050px){.electrical-detail{grid-template-columns:1fr}.electrical-detail figure{max-width:500px}.electrical-detail .el-image{height:200px}}@media(max-width:600px){.agv-electrical{padding:16px}.agv-electrical h2{font-size:16px}.agv-electrical header>.el-button{padding:9px}.electrical-flow{overflow-x:auto}.electrical-flow svg{min-width:560px;height:160px}.electrical-detail{padding-top:16px;gap:16px}}</style>

<style>.agv-electrical-reader.el-dialog{margin:3vh auto!important;margin:3dvh auto!important;max-height:94vh;max-height:94dvh;display:flex;flex-direction:column;overflow:hidden;padding:18px}.agv-electrical-reader .el-dialog__body{min-height:0;overflow:auto;padding:0}.agv-electrical-reader .pdf-surface{max-height:calc(90vh - 125px);max-height:calc(90dvh - 125px)}.agv-electrical-reader .el-dialog__header{padding:0 28px 16px 0;margin:0}</style>

<style scoped>.electrical-systems{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;margin-bottom:20px}.electrical-systems button{min-height:44px;padding:9px 10px;background:#f7fafb;border:1px solid #d9e6eb;border-radius:8px;color:#496f80;font:inherit;font-size:13px;cursor:pointer}.electrical-systems button[aria-pressed=true]{background:#e4f3f5;border-color:#3e96a6;color:#166f80}.electrical-systems button:focus-visible{outline:3px solid #358ba0;outline-offset:2px}@media(max-width:700px){.electrical-flow svg{display:none}.electrical-flow{padding:8px 0 14px}.electrical-flow>small{font-size:11px}.electrical-description p{font-size:13px}.electrical-description>small,.electrical-pages small{font-size:11px}.electrical-pages button{min-height:44px;font-size:13px}}</style>

<style scoped>.agv-electrical>header{margin-bottom:22px}.electrical-systems{grid-template-columns:repeat(6,minmax(0,1fr));gap:6px}.electrical-systems button{font-size:12px;padding:9px 6px}@media(max-width:1000px){.electrical-systems{grid-template-columns:repeat(3,minmax(0,1fr))}}@media(max-width:600px){.electrical-systems{grid-template-columns:repeat(2,minmax(0,1fr))}.agv-electrical>header{align-items:flex-start;flex-wrap:wrap;margin-bottom:14px}.agv-electrical>header>div{flex:1 1 180px;min-width:0}.agv-electrical h2{line-height:1.6;overflow-wrap:anywhere}.agv-electrical>header>.el-button{flex:none;min-height:44px;margin-left:auto}.electrical-pages button>span{min-width:0;overflow-wrap:anywhere}.electrical-pages small{flex-shrink:0}}</style>
